import assert from 'node:assert/strict';
import { createAgentConfirmationStore } from '../followup_cancellation_recovery_20261009/source/server/agent-confirmation-store.ts';
import { createProductAgent } from '../followup_cancellation_recovery_20261009/source/server/product-agent.ts';
import { createStorageCipher } from '../followup_cancellation_recovery_20261009/source/server/storage-crypto.ts';
const userId='synthetic-user',childId='00000000-0000-4000-8000-000000000001',workspaceId='synthetic-workspace';
const confirmationId='00000000-0000-4000-8000-000000000002',proposalId='00000000-0000-4000-8000-000000000003';
const originalRunId='00000000-0000-4000-8000-000000000004',responseId='00000000-0000-4000-8000-000000000005';
const newRunId='00000000-0000-4000-8000-000000000006',factId='00000000-0000-4000-8000-000000000007';
const cipher=createStorageCipher(Buffer.alloc(32,73));
const result={id:proposalId,runId:originalRunId,childId,version:2,status:'accepted',createdAt:'2026-10-09T00:00:00Z',expiresAt:'2026-10-09T00:01:00Z',
 value:{kind:'memory_fact',key:'Synthetic confirmed value',content:'Synthetic historical content from prior authority',validUntil:null,intendedVisibility:'private'},
 result:{kind:'memory_fact',id:factId,version:2},targetLabel:null};
const row={id:confirmationId,owner_user_id:userId,child_id:childId,asking_run_id:originalRunId,proposal_run_id:originalRunId,proposal_id:proposalId,
 proposal_version:1,authorization_version:'1',storage_epoch:'synthetic-epoch',policy_version:1,work_id:null,work_version:null,state:'accepted',
 ask_message_id:'00000000-0000-4000-8000-000000000008',response_message_id:responseId,expires_at:new Date('2026-10-09T00:01:00Z'),
 payload_encrypted:cipher.encrypt(JSON.stringify({hash:'synthetic-hash',question:'Synthetic specific confirmation',shared:false,result}),`agent-confirmation:${childId}:${userId}:${confirmationId}`),
 proposal_owner:userId,proposal_child:childId,proposal_authorization:'1',proposal_epoch:'synthetic-epoch',proposal_state:'accepted',saved_proposal_version:2};
let currentAuthorization='1',decisions=0,businessWrites=0;const queries=[];
const rows=(values=[])=>({rows:values,rowCount:values.length});
const query=async(sql,parameters=[])=>{
 queries.push(sql);if(/^(INSERT|UPDATE|DELETE)/u.test(sql)){businessWrites++;throw new Error('No business writes permitted');}
 if(['BEGIN','COMMIT','ROLLBACK'].includes(sql)||sql.startsWith('SET LOCAL'))return rows();
 if(sql==='SELECT workspace_id FROM children WHERE id=$1')return rows([{workspace_id:workspaceId}]);
 if(sql.startsWith('SELECT owner_user_id, access_version'))return rows([{owner_user_id:userId,access_version:currentAuthorization}]);
 if(sql.startsWith('SELECT 1 FROM children'))return rows([{}]);
 if(sql.startsWith('SELECT access_version::text,storage_epoch::text FROM workspaces'))return rows([{access_version:currentAuthorization,storage_epoch:'synthetic-epoch'}]);
 if(sql.startsWith('SELECT * FROM agent_confirmations WHERE owner_user_id=$1'))return rows([structuredClone(row)]);
 if(sql.includes('FROM agent_confirmations c'))return rows([structuredClone(row)]);
 throw new Error('Unexpected synthetic query: '+sql);
};
const pool={query,connect:async()=>({query,release(){}})};
const confirmations=createAgentConfirmationStore(pool,cipher,async()=>{decisions++;throw new Error('No decision may replay');});
assert.deepEqual(await confirmations.recordedConfirmation(userId,childId,responseId),{proposalId});
assert.deepEqual(await confirmations.consumeConfirmation(userId,childId,responseId),result);
currentAuthorization='2';
await assert.rejects(confirmations.recordedConfirmation(userId,childId,responseId),error=>error.code==='confirmation_receipt_changed');
const stale=await confirmations.consumeConfirmation(userId,childId,responseId);
let receivedConfirmation=null,storedResult=null,runtimeCalls=0;
const store={consumeConfirmation:confirmations.consumeConfirmation,claim:async()=>({runId:newRunId,scope:{userId,childId,workspaceId,authorizationVersion:'2',dataVersion:'synthetic-epoch:8'},
 created:true,sourceMessageId:responseId,state:'running',expiresAt:new Date(Date.now()+60000).toISOString()}),authorize:async()=>true,
 finish:async(_scope,value)=>{storedResult=value;return true;},get:async()=>storedResult};
const agent=createProductAgent({store,runtime:{run:async input=>{runtimeCalls++;receivedConfirmation=input.context.confirmationResult;return {runId:newRunId,status:'stopped',stopReason:'unavailable',text:null,tools:[],counts:{modelCalls:0,toolCalls:0,queryEmbeddings:0}};}},
 memory:{context:async()=>({summary:null,truncated:{messages:false}})},chat:{listForUser:async()=>({messages:[{id:responseId,role:'user',text:'確認'}]})},tasks:{},knowledge:{}});
await agent.reply(userId,childId,responseId,async()=>true);
console.log(JSON.stringify({control:'unchanged authority permits the historical receipt without replay',currentAuthorization,
 guardedReader:'confirmation_receipt_changed',shortcutReturnedOldResult:stale?.value?.content===result.value.content,
 originalProposalRunId:stale?.runId,runtimeCalls,oldConfirmationSentIntoFreshRuntime:receivedConfirmation?.runId===originalRunId,
 decisions,businessWrites,realModelCalls:0}));
assert.equal(decisions,0);assert.equal(businessWrites,0);
assert.equal(receivedConfirmation,null,'An accepted confirmation from an old authorization version must not enter a newly claimed runtime');
